with scored as (select id, store_name, region, opened_date, sqft, round(sqft / sum(sqft) over (partition by region), 4) sqft_share, row_number() over (partition by city order by opened_date desc, id) seq_no, max(sqft) over (partition by region) region_max_sqft, dense_rank() over (partition by date_trunc('month', opened_date), city order by sqft desc nulls last) sqft_dense_rank, sum(sqft) over (partition by region order by opened_date, id rows between unbounded preceding and current row) cumulative_sqft from stores) select id, opened_date, sqft, sqft_share, seq_no, sqft_dense_rank from scored order by id desc nulls first;
